#include <iostream>
#include <memory>
using namespace std;

struct Node { int val; shared_ptr<Node> next; Node(int v, shared_ptr<Node> n) : val(v), next(n) {} };

class PStack {
    shared_ptr<Node> head;
    PStack(shared_ptr<Node> h) : head(h) {}
public:
    PStack() {}
    PStack push(int val) const { return PStack(make_shared<Node>(val, head)); }
    int peek() const { return head->val; }
    PStack pop() const { return PStack(head->next); }
    void print() const {
        auto cur = head;
        while (cur) { cout << cur->val << " "; cur = cur->next; }
        cout << endl;
    }
};

int main() {
    PStack s0;
    auto s1 = s0.push(10);
    auto s2 = s1.push(20);
    auto s3 = s2.push(30);
    cout << "s3: "; s3.print();
    cout << "s2: "; s2.print();
    cout << "s1: "; s1.print();
    return 0;
}
